        // FAQ
        "faq.title": "Frequently Asked Questions",
        "faq.q1": "Do I need a special license to drive a campervan in Japan?",
        "faq.a1": "No special license is needed. Our campervans are regular-sized vehicles that can be driven with a standard International Driving Permit (IDP) or a translated license for certain countries. See the License section above for details.",
        "faq.q2": "Where can I pick up and return the campervan?",
        "faq.a2": "Pick-up and return is at our Hakozaki Base, just 10 minutes from Fukuoka Airport. We can also arrange airport pick-up by prior arrangement. Flexible drop-off locations may be available — just ask!",
        "faq.q3": "What is included in the rental price?",
        "faq.a3": "Everything you need: vehicle insurance (CDW), ETC card (free, pre-registration required), English navigation, basic camping gear (chairs, table, cooking set), portable power station, 24/7 roadside assistance, and multilingual support. No hidden fees!",
        "faq.q4": "What is the cancellation policy?",
        "faq.a4": "Free cancellation up to 8 days before scheduled pick-up. Cancellations within 7 days incur a tiered cancellation fee. Please see our Rental Terms & Conditions page for details.",
        "faq.q5": "Can I sleep in the campervan anywhere?",
        "faq.a5": "Japan has many great options: auto-campsites, RV parks, and \"Michi-no-Eki\" roadside stations. While you can't camp just anywhere, there are hundreds of spots across Kyushu. We'll provide a recommended spot guide when you pick up!",
        "faq.q6": "Can I drop off the campervan in Tokyo or Osaka?",
        "faq.a6": "Yes! One-way trips are available. Pick up in Fukuoka and drop off in Tokyo or Osaka (or vice versa). A surcharge applies depending on the destination. Contact us via WhatsApp or LINE for a quote — we'll work out the best route for your itinerary!",
        "faq.q7": "I'm from Singapore. What do I need to drive in Japan?",
        "faq.a7": "Singapore is a Geneva Convention country, so you need an International Driving Permit (IDP). Get it from AA Singapore for about SGD 20 — it's available same-day at their offices. Bring both your original Singapore driving licence and the IDP. Direct flights from Changi to Fukuoka take just 3.5 hours, and our base is 10 minutes from the airport!",

