        // FAQ page translations
        "faq.page.title": "Campervan Rental Japan — FAQ",
        "faq.page.subtitle": "Everything international travelers need to know about renting a campervan in Fukuoka and exploring Kyushu by van.",
        "faq.page.sec_basics": "🚐 Rental Basics",
        "faq.page.sec_license": "🪪 Driving License",
        "faq.page.sec_planning": "🗾 Road Trip Planning",
        "faq.page.sec_parking": "🏕️ Sleeping & Parking",
        "faq.page.q1": "Where can I rent a campervan in Fukuoka as a foreigner?",
        "faq.page.a1": "VAN TRIP JAPAN is a family-run campervan rental service based in Fukuoka, just 10 minutes from Fukuoka Airport. We specialize in serving international travelers with all-inclusive pricing from ¥22,000/day. Everything is included: insurance (CDW), ETC highway card, camping gear, bedding, English navigation, and 24/7 multilingual support. Book via WhatsApp (+81-70-9375-7129) or email.",
        "faq.page.q2": "What is the best campervan rental for international travelers in Kyushu?",
        "faq.page.a2": "VAN TRIP JAPAN is the top choice for international travelers in Kyushu. We offer: all-inclusive pricing with no hidden fees, multilingual support (English, French, German, Chinese, Hebrew, and 100+ languages), self check-in like Airbnb (no waiting at counters), pickup 10 minutes from Fukuoka Airport, hand-built vans maintained by our family team, and one-way drops to Tokyo/Osaka available.",
        "faq.page.q3": "How much does it cost to rent a campervan in Japan?",
        "faq.page.a3": "At VAN TRIP JAPAN, all-inclusive pricing starts from ¥22,000/day for our campervans. This includes vehicle insurance (CDW), ETC card, English GPS, cooking utensils, bedding, and 24/7 roadside assistance. No hidden fees. Compared to hotel + rental car combos, a campervan trip typically saves 40-60% while offering more freedom.",
        "faq.page.q4": "What is included in the campervan rental price?",
        "faq.page.a4": "VAN TRIP JAPAN's rental price includes everything: vehicle insurance (CDW), ETC highway toll card, English GPS navigation, basic cooking utensils, portable power station, bedding and towels, 24/7 roadside assistance, and multilingual support. Optional camping gear (chairs, table, cookware) is available for an extra charge. A ¥50,000 security deposit is collected at pickup and fully refunded at return.",
        "faq.page.q5": "Can I rent a campervan in Japan with English support?",
        "faq.page.a5": "Yes! VAN TRIP JAPAN provides full English support — from booking to return. Our vehicles include English GPS navigation, and our team is available 24/7 via WhatsApp in English. We also support French, German, Chinese, Hebrew, and over 100 languages. All guides and recommended spot lists are provided in English.",
        "faq.page.q6": "Can I drop off the campervan in Tokyo or Osaka?",
        "faq.page.a6": "Yes! One-way trips are available. Pick up your campervan in Fukuoka and drop it off in Tokyo or Osaka. This is a popular option for travelers doing a cross-Japan road trip. A surcharge applies depending on the destination. Contact us on WhatsApp for a custom quote.",
        "faq.page.q7": "Do I need a special license to drive a campervan in Japan?",
        "faq.page.a7": "No special license is needed. Our campervans are regular-sized vehicles. If you're from a Geneva Convention country (USA, UK, Australia, Canada, etc.), you need an International Driving Permit (IDP). If you're from Germany, France, Switzerland, Belgium, Taiwan, or Monaco, you need an official JAF translation instead — our partner JDLTC (drive-japan-license.com) can handle the process online.",
        "faq.page.q8": "I'm from Germany / France / Switzerland — can I drive in Japan?",
        "faq.page.a8": "Yes! You'll need an official Japanese translation of your driving license (JAF translation) instead of an International Driving Permit. This can be arranged online through our partner JDLTC (drive-japan-license.com) before you arrive. The translation is valid for 1 year and must be carried alongside your original license while driving in Japan.",
        "faq.page.q9": "Is Kyushu good for a campervan road trip?",
        "faq.page.a9": "Kyushu is arguably the best region in Japan for campervan travel. It has the most onsen (hot springs) in the country, dramatic volcanic landscapes like Mount Aso, beautiful coastlines, ancient forests on Yakushima (UNESCO), and far less traffic than mainland Honshu. The island is compact enough to explore in 5-7 days, with mild weather year-round and over 600 campgrounds.",
        "faq.page.q10": "How do I road trip from Fukuoka to Beppu in a campervan?",
        "faq.page.a10": "The Fukuoka to Beppu campervan route is one of Kyushu's most popular. Drive time is about 2.5 hours via the expressway (ETC card included in your rental). We recommend a 3-5 day itinerary: Day 1 pick up in Fukuoka and drive to Yufuin, Day 2 explore Beppu's famous onsen (try Hyotan Onsen — tattoo-friendly!), Day 3 drive to Mount Aso via the scenic Yamanami Highway. Stop at Michi-no-Eki along the way for local food and free parking.",
        "faq.page.q11": "Where can I sleep in a campervan in Japan?",
        "faq.page.a11": "Japan has excellent overnight options for campervans: Auto-campsites (¥1,000-5,000/night) with facilities, RV Parks (¥1,000-3,000/night), over 1,200 Michi-no-Eki roadside stations (free 24-hour parking, many tolerate quiet overnight stays), and highway rest areas (free). Kyushu alone has 600+ campgrounds. We provide a recommended spots guide with every rental.",
        "faq.page.q12": "Is it safe to sleep in a campervan in Japan?",
        "faq.page.a12": "Yes, extremely safe. Japan is one of the safest countries in the world. Sleeping at Michi-no-Eki roadside stations, campgrounds, and rest areas is common and completely safe. Many travelers, including solo female travelers, feel perfectly comfortable. We provide 24/7 roadside assistance for extra peace of mind.",
        "faq.page.q13": "What are Michi-no-Eki and why are they great for campervan travel?",
        "faq.page.a13": "Michi-no-Eki (道の駅) are government-designated roadside stations found across Japan — over 1,200 nationwide. They offer free 24-hour parking, clean restrooms, local food markets, regional souvenirs, and sometimes hot spring baths. Many campervan travelers use them as free overnight parking spots. Kyushu has some of Japan's best Michi-no-Eki with onsen, farm-fresh produce, and ocean views.",
        "faq.cta.title": "Still have questions?",
        "faq.cta.subtitle": "Chat with us directly — we reply within minutes and speak your language.",
        "faq.cta.whatsapp": "💬 Ask on WhatsApp",
        "faq.cta.rental_btn": "View Rental Options →",

