        "home.banner.tag": "Pickup 10 min from Fukuoka Airport",
        "home.banner.title": "Your campervan is waiting",
        "home.banner.desc": "Self check-in, no paperwork, no counters. Grab the keys from our lockbox and start driving — even if your flight lands at midnight.",
