        "home.guides.title": "Popular Travel Guides",
        "home.guide1.title": "Campervan vs Hotel: The Real Cost Comparison",
        "home.guide1.desc": "Is renting a campervan actually cheaper than booking hotels and trains? We break down the real numbers for a 7-day road trip in Kyushu.",
        "home.guide2.title": "Can Foreigners Drive in Japan? License & IDP Requirements",
        "home.guide2.desc": "Everything you need to know about International Driving Permits (IDP), Japanese license translations, and traffic rules.",
        "home.guides.read": "Read Guide →",
        "home.facts.title": "Driving & Vanlife in Japan: Essential Facts",
        "home.facts.rules": "<strong style=\"color: var(--color-accent, #d4a853);\">Driving Rules:</strong> Japan drives on the left side of the road. Speed limits are typically 30–40 km/h in urban areas, 50–60 km/h on national roads, and 80–120 km/h on expressways. All passengers must wear seatbelts, and the legal blood alcohol limit is 0.0% — Japan enforces a strict zero-tolerance policy for drinking and driving.",
        "home.facts.license": "<strong style=\"color: var(--color-accent, #d4a853);\">License Requirements:</strong> Visitors from countries that signed the 1949 Geneva Convention (USA, UK, Australia, etc.) can drive with an International Driving Permit (IDP). Visitors from Switzerland, Germany, France, Belgium, Monaco, and Taiwan need an official Japanese translation of their license (<a href=\"https://drive-japan-license.com/\" target=\"_blank\" style=\"color: var(--color-accent, #d4a853); text-decoration: underline;\">available via JDLTC</a>).",
        "home.facts.camping": "<strong style=\"color: var(--color-accent, #d4a853);\">Camping Spots:</strong> Kyushu has over 200 campgrounds, including free municipal sites (michi-no-eki) and premium glamping facilities. Popular destinations include Aso Caldera, Beppu hot springs, Kunisaki Peninsula, Yakushima, and the Kirishima mountain range.",
        "home.facts.author": "<strong>Written by:</strong> Doko & Karen, founders of VAN TRIP JAPAN. A husband-and-wife team based in Fukuoka who have explored all 47 prefectures by van.",
        "home.facts.updated": "<strong>Last updated:</strong> <time datetime=\"2026-06-13\">June 13, 2026</time> | <strong>References:</strong> <a href=\"https://www.npa.go.jp/english/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">National Police Agency of Japan</a>, <a href=\"https://www.jaf.or.jp/e/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">Japan Automobile Federation (JAF)</a>",

