        "faq.title": "Questions Fréquentes",
        "faq.q1": "Ai-je besoin d'un permis spécial pour conduire un camping-car au Japon ?",
        "faq.a1": "Non. Nos camping-cars sont des véhicules de taille normale, conduisibles avec un permis de conduire international (PCI) standard ou une traduction officielle pour certains pays.",
        "faq.q2": "Où puis-je récupérer et rendre le camping-car ?",
        "faq.a2": "À notre base Hakozaki, à 10 minutes de l'aéroport de Fukuoka. Nous pouvons aussi organiser un transfert depuis l'aéroport sur demande.",
        "faq.q3": "Qu'est-ce qui est inclus dans le prix ?",
        "faq.a3": "Tout : assurance, carte ETC (gratuite, inscription préalable requise), navigation, matériel de camping, station d'alimentation portable, assistance 24h/24 et support multilingue. Aucun frais caché !",
        "faq.q4": "Quelle est la politique d'annulation ?",
        "faq.a4": "Annulation gratuite jusqu'à 8 jours avant. Les annulations dans les 7 jours entraînent des frais échelonnés. Veuillez consulter nos conditions de location pour plus de détails.",
        "faq.q5": "Puis-je dormir n'importe où dans le camping-car ?",
        "faq.a5": "Le Japon offre de nombreuses options : campings auto, parcs RV et stations routières « Michi-no-Eki ». Nous vous fournirons un guide des meilleurs spots lors de la prise en charge !",
        "faq.q6": "Puis-je rendre le camping-car à Tokyo ou Osaka ?",
        "faq.a6": "Oui ! Les trajets aller simple sont disponibles. Prise en charge à Fukuoka et retour à Tokyo ou Osaka (ou vice versa). Un supplément s'applique selon la destination. Contactez-nous via WhatsApp ou LINE pour un devis !",
        "faq.q7": "Je viens de Singapour. De quoi ai-je besoin pour conduire au Japon ?",
        "faq.a7": "Singapour est un pays signataire de la Convention de Genève, vous avez donc besoin d'un PCI. Obtenez-le auprès d'AA Singapore pour environ SGD 20 — disponible le jour même. Apportez votre permis original et le PCI. Les vols directs Changi-Fukuoka ne durent que 3h30 !",

