        // Reviews
        "reviews.badge": "Réel & Vérifiable",
        "trust.licensed": "Loueur de véhicules agréé",
        "trust.reviews": "Entreprise familiale à Fukuoka depuis 2022",
        "trust.countries": "Support multilingue 🇬🇧 🇫🇷 🇩🇪 🇹🇼 🇮🇱",
        "reviews.proof1_t": "Loueur de véhicules agréé",
        "reviews.proof1_d": "Permis n° 愛運輸第290号 — une activité de location réglementée, pas un intermédiaire.",
        "reviews.proof2_t": "Société japonaise enregistrée",
        "reviews.proof2_d": "キャンプ女子株式会社 · N° d'entreprise 2290001085571 — vérifiable sur le registre officiel du Japon.",
        "reviews.proof3_t": "Gérée par Karen & son mari",
        "reviews.proof3_d": "C'est nous sur la photo ci-dessus — vous parlez à une vraie personne, pas à un centre d'appels.",
        "reviews.proof4_t": "Une vraie base sur Google Maps",
        "reviews.proof4_d": "Hakozaki, Fukuoka — à 10 min de l'aéroport. Venez voir les vans en personne.",
        "reviews.proof5_t": "Réservé par des voyageurs du monde entier",
        "reviews.proof5_d": "Des clients récents des 🇳🇱 Pays-Bas, 🇬🇧 Royaume-Uni, 🇸🇬 Singapour, 🇫🇷 France, 🇮🇱 Israël, et bien d'autres — nous accueillons les aventuriers du monde entier.",
        "reviews.note": "Voyagé avec nous ? Un petit avis Google compte énormément pour une entreprise familiale 🙏",
        "sticky.google": "📍 Sur Google ↗",
        "reviews.title": "Une vraie entreprise familiale agréée",
        "reviews.subtitle": "Nous sommes une jeune entreprise — alors plutôt que des avis invérifiables, voici des preuves que vous pouvez vérifier vous-même.",
        "reviews.r1_meta": "7 jours · Bongo · Couple",
        "reviews.r1_text": "\"Nous avons exploré Aso, Beppu et la péninsule de Kunisaki pendant 7 jours. Le van était impeccable et bien équipé. C'était notre troisième fois au Japon mais la première fois que nous nous sommes vraiment sentis libres. Absolument recommandé !\"",
        "reviews.r2_meta": "14 jours · Probox · Couple",
        "reviews.r2_text": "\"14 jours incroyables à Kyushu ! Le camping-car avait tout ce qu'il fallait. On a dormi au bord de la mer à Yakushima et aux pieds des montagnes d'Aso. Le support multilingue en français était un vrai plus. Merci VAN TRIP JAPAN !\"",
        "reviews.r3_meta": "10 jours · Bongo · Couple",
        "reviews.r3_text": "\"Nous avons conduit de Fukuoka jusqu'à Kagoshima et retour par les montagnes. Les arrêts onsen en chemin étaient incroyables — rien ne vaut une source chaude après une journée de conduite. L'équipe nous a aidés à planifier tout l'itinéraire. Les meilleures vacances de notre vie !\"",
        "reviews.r4_meta": "5 jours · Probox · Solo",
        "reviews.r4_text": "\"En tant que voyageuse solo, je me suis sentie en totale sécurité. Le Probox était parfait pour une personne. Les Michi-no-Eki étaient parfaits pour dormir. J'aurais aimé réserver plus longtemps !\"",

