        "quote.submit": "📧 Envoyez-moi un devis",
        "quote.note": "Nous inclurons vos paramètres calculateur (véhicule, jours, voyageurs) dans le devis.",
        "quote.success": "Demande de devis envoyée !",
        "quote.success_detail": "Vérifiez votre boîte mail sous 24h. Vous pouvez aussi nous contacter sur WhatsApp.",
        "story.sec1_badge": "👫 Notre Histoire",
        "story.sec1_title": "Deux personnes, une flotte 100% japonaise, une passion commune",
        "story.sec1_subtitle": "Nous ne sommes pas une grande entreprise. Nous sommes un couple marié qui sélectionne et prend soin de chaque véhicule.",
        "story.sec1_text1": "Pas de centre d'appels, pas de script d'entreprise, pas de service impersonnel. Lorsque vous louez chez nous, vous êtes soutenu directement par nous — des vanlifers expérimentés qui ont passé des années sur la route. Nous avons sélectionné chacun de nos véhicules japonais sûrs, fiables et de haute sécurité selon notre propre expérience. Chaque van offre une excellente efficacité énergétique et une conduite très facile sur les routes étroites et sinueuses du Japon.",
        "story.sec1_text2": "VAN TRIP JAPAN est fondé et géré par Karen, une véritable passionnée de plein air depuis toujours, et son mari. Nous avons créé cette petite boutique car nous croyons que voyager en camping-car au Japon doit être sûr, chaleureux et authentique. Nous sommes là pour soutenir votre voyage avec une assistance personnelle 24h/24 et 7j/7, des itinéraires sur mesure et les meilleurs conseils locaux.",

        "story.label": "🏠 Notre Histoire",
        "story.caption": "👋 Karen & son mari — vos hôtes",
        "story.title": "Un couple de vrais passionnés de Vanlife",
        "story.sub": "Une flotte 100% japonaise, sélectionnée pour sa sécurité et son excellente efficacité énergétique.",
        "story.text": "Nous sommes un petit magasin de location de camping-cars géré en couple à Fukuoka. En tant que vanlifers expérimentés, nous choisissons chaque véhicule du point de vue d'un voyageur professionnel. Notre flotte est composée exclusivement de voitures japonaises de haute qualité et de grande sécurité (telles que les Hijet Truck, Bongo et Probox super fiables)—garantissant les normes de sécurité les plus élevées, une conduite extrêmement facile et une faible consommation de carburant. Notre propriétaire, Karen, est une véritable passionnée de plein air. Nous avons conçu et aménagé ces vans nous-mêmes pour vous offrir un voyage sûr, chaleureux et authentique au cœur du Japon.",
        "story.p1_title": "Mari & Femme",
        "story.p1_desc": "Une petite équipe passionnée de vanlifers expérimentés.",
        "story.p2_title": "Véhicules 100% Japonais",
        "story.p2_desc": "Sécurité maximale, grande fiabilité et économie de carburant.",
        "story.p3_title": "Passion Plein Air",
        "story.p3_desc": "Géré par Karen, une amoureuse inconditionnelle de la nature.",
        "story.quote": "\"Nous ne faisons pas que louer des camping-cars. Nous partageons des vans personnalisés et conçus après des années de vanlife, pour un voyage sûr, vert et inoubliable.\"",
        "vehicles.probox_story": "Notre explorateur compact. Excellente économie de carburant, extrêmement compact et facile à garer, avec 5 sièges et un espace bagage massif. Parfait pour les couples.",
        "vehicles.bongo_story": "Notre cruiser fait main. Assez spacieux pour se détendre et s'amuser à l'intérieur même les jours de pluie. Malgré sa grande taille, sa largeur étroite le rend incroyablement facile à conduire.",
        "vehicles.daihatsu_badge": "🆕 NOUVEAU · 1er JUILLET",
        "vehicles.daihatsu_name": "Pocket Loft",
        "vehicles.daihatsu_story": "Notre explorateur ultra-compact avec tente de toit, construit sur la base ultra-sûre et fiable du Daihatsu Hijet Truck. Capable d'accueillir jusqu'à 4 personnes (2 dans la tente de toit, 2 dans l'habitacle) avec un accès intérieur direct. Parfait pour les couples recherchant une conduite facile, une excellente économie de carburant et de superbes paysages.",
        "vehicles.spec_rooftent_indoor": "Accès intérieur à la tente",
        "vehicles.spec_panorama": "Vues panoramiques",
        "vehicles.spec_easy": "Le plus facile à conduire",
