        "vehicles.daihatsu_island_badge": "IDÉAL POUR LES FERRIES",
        "vehicles.spec_ferry": "Tarif ferry le moins cher",
        "vehicles.daihatsu_island_tip": "Très populaire auprès des voyageurs vers Yakushima et les îles Goto ! Véhicule le plus court = tarif ferry le moins cher + réservation la plus facile. Fortement recommandé pour le island hopping.",
