        "home.stories.tag": "Nouveautés",
        "home.stories.title": "Quoi de neuf",
        "home.cat1.title": "Guide du voyage en van",
        "home.cat1.desc": "Conseils, itinéraires et location — l'essentiel du voyage en van.",
        "home.cat2.title": "Explorer les destinations",
        "home.cat2.desc": "Panoramas et trésors cachés de Kyushu et au-delà.",
        "home.banner.tag": "Prise en charge à 10 min de l'aéroport de Fukuoka",
        "home.banner.title": "Votre van vous attend",
        "home.banner.desc": "Check-in autonome, zéro paperasse, zéro comptoir. Récupérez les clés dans notre boîte sécurisée et prenez la route — même si votre vol atterrit à minuit.",
        "home.banner.cta": "Voir les vans disponibles →",
        "home.news.title": "Kit de démarrage gratuit pour votre road trip à Kyushu",
        "home.news.desc": "Notre carte des onsen, guide des spots de stationnement et conseils de conduite pour débutants — tout ce qu'on aurait aimé savoir à nos débuts.",
        "home.news.placeholder": "Adresse e-mail",
        "home.news.btn": "S'abonner",
        "home.guides.tag": "Recommandés",
        "home.guides.title": "Guides de voyage populaires",
        "home.guide1.title": "Van aménagé ou hôtel : le vrai comparatif des coûts",
        "home.guide1.desc": "Louer un van revient-il vraiment moins cher que les hôtels et les trains ? Le vrai calcul pour un road trip de 7 jours à Kyushu.",
        "home.guide2.title": "Conduire au Japon : permis et traduction obligatoire",
        "home.guide2.desc": "Tout savoir sur le permis international (AIDP), la traduction japonaise obligatoire pour les permis français et le code de la route.",
        "home.guides.read": "Lire le guide →",
        "home.facts.title": "Conduire et voyager en van au Japon : l'essentiel",
        "home.facts.rules": "<strong style=\"color: var(--color-accent, #d4a853);\">Code de la route :</strong> Au Japon, on roule à gauche. Limitations : environ 30–40 km/h en ville, 50–60 km/h sur routes nationales et 80–120 km/h sur autoroute. Ceinture obligatoire pour tous les passagers, taux d'alcool autorisé 0,0 % — tolérance zéro absolue au volant.",
        "home.facts.license": "<strong style=\"color: var(--color-accent, #d4a853);\">Permis de conduire :</strong> Les visiteurs des pays signataires de la Convention de Genève de 1949 (États-Unis, Royaume-Uni, Australie…) peuvent conduire avec un permis international (AIDP). Les visiteurs venant de France, Suisse, Allemagne, Belgique, Monaco et Taïwan ont besoin d'une traduction japonaise officielle de leur permis (<a href=\"https://drive-japan-license.com/\" target=\"_blank\" style=\"color: var(--color-accent, #d4a853); text-decoration: underline;\">disponible via JDLTC</a>).",
        "home.facts.camping": "<strong style=\"color: var(--color-accent, #d4a853);\">Camping :</strong> Kyushu compte plus de 200 campings, des aires municipales gratuites (michi-no-eki) aux glampings haut de gamme. Destinations phares : caldeira d'Aso, sources chaudes de Beppu, péninsule de Kunisaki, Yakushima et massif de Kirishima.",
        "home.facts.author": "<strong>Rédigé par :</strong> Doko & Karen, fondateurs de VAN TRIP JAPAN. Un couple installé à Fukuoka qui a exploré les 47 préfectures du Japon en van.",
        "home.facts.updated": "<strong>Dernière mise à jour :</strong> <time datetime=\"2026-06-13\">13 juin 2026</time> | <strong>Sources :</strong> <a href=\"https://www.npa.go.jp/english/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">Agence nationale de police du Japon</a>, <a href=\"https://www.jaf.or.jp/e/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">Fédération japonaise de l'automobile (JAF)</a>",

