        "book.license.body": "Pour conduire au Japon, il vous faut :<ul style=\"margin-top: 4px; padding-left: 16px; list-style-type: disc;\"><li>le permis de conduire valide de votre pays ET</li><li>un <strong>permis de conduire international (AIDP)</strong> délivré selon la <strong>Convention de Genève de 1949</strong>. (Attention : les AIDP de la Convention de Vienne de 1968 — dont les AIDP français — ne sont PAS valables au Japon.)</li><li><em>Conducteurs de France, Suisse, Allemagne, Belgique, Monaco, Taïwan :</em> il vous faut une traduction japonaise officielle de votre permis (via JDLTC ou JAF) à la place de l'AIDP.</li></ul>",
