        "reviews.proof3_t": "Persönlich geführt von Karen & ihrem Mann",
        "reviews.proof3_d": "Das sind wir auf dem Foto oben — du sprichst mit einem echten Menschen, keinem Callcenter.",
        "reviews.proof4_t": "Eine echte Basis auf Google Maps",
        "reviews.proof4_d": "Hakozaki, Fukuoka — 10 Min. vom Flughafen. Besuche die Vans jederzeit persönlich.",
        "reviews.proof5_t": "Gebucht von Reisenden weltweit",
        "reviews.proof5_d": "Kürzliche Gäste aus 🇳🇱 Niederlande, 🇬🇧 Vereinigtes Königreich, 🇸🇬 Singapur, 🇫🇷 Frankreich, 🇮🇱 Israel und mehr — wir begrüßen Abenteurer aus aller Welt.",
        "reviews.note": "Mit uns gereist? Eine kurze Google-Bewertung bedeutet einem kleinen Familienbetrieb die Welt 🙏",
