        // Our Story
        "story.sec1_badge": "👫 Unsere Geschichte",
        "story.sec1_title": "Zwei Menschen, 100 % japanische Flotte, eine gemeinsame Leidenschaft",
        "story.sec1_subtitle": "Wir sind kein riesiger Vermietungskonzern. Wir sind ein Ehepaar, das jedes einzelne Fahrzeug handverliest und liebt.",
        "story.sec1_text1": "Es gibt kein Callcenter, kein Firmenskript und keinen unpersönlichen Service. Wenn Sie bei uns mieten, werden Sie direkt von uns unterstützt – erfahrenen Vanlifern, die jahrelang auf der Straße unterwegs waren. Wir haben jedes unserer sicheren, hochgradig zuverlässigen japanischen Fahrzeuge aus unserer eigenen Vanlife-Perspektive ausgewählt. Jeder Van bietet eine hervorragende Kraftstoffeffizienz und lässt sich auf Japans engen, kurvenreichen Panoramastraßen extrem leicht fahren.",
        "story.sec1_text2": "VAN TRIP JAPAN wurde von Karen, einer echten und leidenschaftlichen Outdoor-Liebhaberin, zusammen mit ihrem Ehemann gegründet und betrieben. Wir haben diesen kleinen Laden aufgebaut, weil wir glauben, dass Campervan-Reisen in Japan sicher, herzlich und authentisch sein sollten. Wir sind hier, um Ihre Reise mit rund um die Uhr persönlicher Betreuung, maßgeschneiderten Routen und den besten lokalen Tipps zu unterstützen, die Sie in keinem Reiseführer finden.",

        "story.label": "🏠 Unsere Geschichte",
        "story.caption": "👋 Karen & ihr Mann — eure Gastgeber",
        "story.title": "Ein Familien-Campervan-Abenteuer",
        "story.sub": "Kleines Unternehmen. Großes Herz. Handgebaute Vans.",
        "story.text": "Wir sind ein kleines Familienteam aus Fukuoka. 2022 haben wir unsere Vans selbst umgebaut — Betten gebaut, Stromsysteme installiert, Innenräume gestaltet — weil wir das Reiseerlebnis schaffen wollten, das wir selbst lieben würden.",
        "story.p1_title": "Familienbetrieb",
        "story.p1_desc": "Kein Konzern. Eine Familie, die Roadtrips liebt.",
        "story.p2_title": "Handgefertigt",
