        "story.quote": "\"Wir haben kein Mietunternehmen gegründet. Wir haben Vans gebaut, in denen wir selbst reisen wollen.\"",
        "vehicles.probox_story": "Unser kompakter Entdecker. Hervorragende Kraftstoffeffizienz, extrem kompakt und leicht zu parken, mit 5 Sitzen und riesigem Gepäckraum. Perfekt für Paare.",
        "vehicles.bongo_story": "Unser handgebauter Cruiser. Geräumig genug, um sich auch an regnerischen Tagen im Inneren zu entspannen. Trotz seiner Größe ist die Breite schmal, was das Fahren in Japan super einfach macht.",
