        // Home page translations
        "home.hero.badge": "🇩🇪 Familiengeführte Wohnmobil- & Campervan-Vermietung in Fukuoka",
        "home.hero.title": "Erkunden Sie Kyushu<br>Auf Ihre Weise",
        "home.hero.desc": "Wir sind ein Ehepaar, das handgefertigte Campervans in Fukuoka vermietet. Onsen-Hopping in Beppu, Fahrt am Kraterrand des Aso und Aufwachen mit Meerblick — alles inklusive ab ¥22.000/Tag.",
