        "home.hero.cta_rent": "Wohnmobil mieten →",
        "home.hero.cta_guides": "Reiseführer lesen",
        "home.hero.trust1": "🚐 Ab ¥22.000/Tag (ca. 119 €)",
        "home.hero.trust2": "📍 10 Min. vom Flughafen",
