        "home.stories.tag": "Aktuell",
        "home.stories.title": "Neuigkeiten",
        "home.cat1.title": "Van-Reiseguide",
        "home.cat1.desc": "Tipps, Routen und Mietinfos — die Grundlagen fürs Reisen im Van.",
        "home.cat2.title": "Ziele entdecken",
        "home.cat2.desc": "Aussichtspunkte und Geheimtipps in Kyushu und darüber hinaus.",
        "home.banner.tag": "Abholung 10 Min. vom Flughafen Fukuoka",
        "home.banner.title": "Dein Campervan wartet schon",
        "home.banner.desc": "Self-Check-in, kein Papierkram, kein Schalter. Schlüssel aus der Lockbox nehmen und losfahren — auch wenn dein Flug um Mitternacht landet.",
        "home.banner.cta": "Fahrzeuge ansehen →",
        "home.news.title": "Kostenloses Kyushu-Roadtrip-Starterpaket",
        "home.news.desc": "Unsere Onsen-Karte, unser Stellplatz-Guide und Fahrtipps für Einsteiger — alles, was wir am Anfang gern gewusst hätten.",
        "home.news.placeholder": "E-Mail-Adresse",
        "home.news.btn": "Abonnieren",
        "home.guides.tag": "Empfohlen",
        "home.guides.title": "Beliebte Reiseguides",
        "home.guide1.title": "Campervan oder Hotel: der ehrliche Kostenvergleich",
        "home.guide1.desc": "Ist ein Campervan wirklich günstiger als Hotels und Züge? Wir rechnen einen 7-tägigen Kyushu-Roadtrip durch.",
        "home.guide2.title": "Autofahren in Japan: Führerschein & Pflicht-Übersetzung",
        "home.guide2.desc": "Alles über internationale Führerscheine (IDP), die für deutsche Führerscheine nötige japanische Übersetzung und die Verkehrsregeln.",
        "home.guides.read": "Guide lesen →",
        "home.facts.title": "Autofahren & Vanlife in Japan: die wichtigsten Fakten",
        "home.facts.rules": "<strong style=\"color: var(--color-accent, #d4a853);\">Verkehrsregeln:</strong> In Japan gilt Linksverkehr. Tempolimits: ca. 30–40 km/h innerorts, 50–60 km/h auf Landstraßen und 80–120 km/h auf Autobahnen. Anschnallpflicht für alle Insassen, Promillegrenze 0,0 — Japan verfolgt eine strikte Null-Toleranz-Politik am Steuer.",
        "home.facts.license": "<strong style=\"color: var(--color-accent, #d4a853);\">Führerschein:</strong> Besucher aus Ländern der Genfer Konvention von 1949 (USA, UK, Australien u.a.) fahren mit internationalem Führerschein (IDP). Besucher aus Deutschland, der Schweiz, Frankreich, Belgien, Monaco und Taiwan brauchen eine offizielle japanische Übersetzung ihres Führerscheins (<a href=\"https://drive-japan-license.com/\" target=\"_blank\" style=\"color: var(--color-accent, #d4a853); text-decoration: underline;\">erhältlich über JDLTC</a>).",
        "home.facts.camping": "<strong style=\"color: var(--color-accent, #d4a853);\">Campingplätze:</strong> Kyushu hat über 200 Campingplätze — von kostenlosen Rastplätzen (Michi-no-Eki) bis zu Premium-Glamping. Beliebte Ziele: Aso-Caldera, die heißen Quellen von Beppu, die Kunisaki-Halbinsel, Yakushima und das Kirishima-Gebirge.",
        "home.facts.author": "<strong>Verfasst von:</strong> Doko & Karen, Gründer von VAN TRIP JAPAN. Ein Ehepaar aus Fukuoka, das alle 47 Präfekturen Japans im Van bereist hat.",
        "home.facts.updated": "<strong>Zuletzt aktualisiert:</strong> <time datetime=\"2026-06-13\">13. Juni 2026</time> | <strong>Quellen:</strong> <a href=\"https://www.npa.go.jp/english/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">Nationale Polizeibehörde Japans</a>, <a href=\"https://www.jaf.or.jp/e/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">Japan Automobile Federation (JAF)</a>",

