        "faq.title": "常見問題",
        "faq.q1": "在日本駕駛露營車需要特別的駕照嗎？",
        "faq.a1": "不需要。我們的露營車是普通大小的車輛，可以使用標準的國際駕照（IDP）或特定國家的翻譯駕照駕駛。",
        "faq.q2": "在哪裡取車和還車？",
        "faq.a2": "在我們的箱崎基地，距福岡機場僅10分鐘。我們也可以安排機場接送。",
        "faq.q3": "租車價格包含什麼？",
        "faq.a3": "所有東西：保險、ETC卡（免費，需事前申請）、導航、露營裝備、行動電源、24/7道路救援及多語言支援。沒有隱藏費用！",
        "faq.q4": "取消政策是什麼？",
        "faq.a4": "預約出發8天前可免費取消。7天內取消將收取分級取消手續費。詳情請參閱我們的租賃條款與條件頁面。",
        "faq.q5": "可以在任何地方睡在露營車裡嗎？",
        "faq.a5": "日本有很多選擇：汽車露營場、RV停車場和「道之驛」休息站。我們會在取車時提供推薦景點指南！",
        "faq.q6": "可以在東京或大阪還車嗎？",
        "faq.a6": "可以！提供單程服務。在福岡取車，在東京或大阪還車（或反向）。依目的地收取附加費用。請通過WhatsApp或LINE聯繫我們取得報價！",
        "faq.q7": "我來自新加坡，在日本開車需要什麼？",
        "faq.a7": "新加坡是日內瓦公約國家，您需要國際駕照（IDP）。在AA Singapore取得，約SGD 20，當天可取。攜帶您的原始新加坡駕照和IDP。樟宜到福岡的直飛僅3.5小時，我們的基地距機場僅10分鐘！",

