        "reviews.proof4_d": "福岡箱崎 — 距機場10分鐘。隨時歡迎親自來看車。",
        "reviews.proof5_t": "來自世界各國的旅客預約",
        "reviews.proof5_d": "最近的客人來自 🇳🇱 荷蘭、🇬🇧 英國、🇸🇬 新加坡、🇫🇷 法國、🇮🇱 以色列等國 — 歡迎來自世界各地的冒險家！",
        "reviews.note": "與我們同遊過嗎？一則簡短的 Google 評論對家族小生意意義重大 🙏",
