        // Our Story
        "story.sec1_badge": "👫 我們的故事",
        "story.sec1_title": "兩個人，100% 日本車隊，同一個共同熱情",
        "story.sec1_subtitle": "我們不是龐大的租賃企業。我們是一對夫妻，親自挑選並熱愛每一輛車。",
        "story.sec1_text1": "這裡沒有呼叫中心，沒有企業指令，也沒有冰冷的服務。當您向我們租車時，您將直接得到我們的支持——我們是經驗豐富的露營車旅人，曾在旅途中度過多年時光。我們從自身露營生活的角度出發，挑選了每一輛安全、高安全性且極其可靠的日本車輛。每輛車都具有出色的燃油效率，並且在日本狹窄、彎曲的風景道路上極易駕駛。",
        "story.sec1_text2": "VAN TRIP JAPAN 由 Karen 及其丈夫共同創立和運營，她是一位真正熱愛戶外運動的終身愛好者。我們建立這家小店，是因為我們相信在日本的露營車旅行應該是安全、溫馨和真實的。我們隨時為您的旅程提供 24/7 的個人關懷、定制路線以及在任何旅遊指南中都找不到的最佳當地實用建議。",

        "story.label": "🏠 我們的故事",
        "story.caption": "👋 Karen 與她的先生 — 您的主人",
        "story.title": "家族經營的露營車冒險",
        "story.sub": "小型企業。滿滿熱情。手工改裝。",
        "story.text": "我們是位於福岡的小型家族團隊。2022年，我們親手改裝了自己的車輛——製作床鋪、安裝電力系統、佈置內裝——因為我們想創造自己也會愛上的旅行體驗。",
        "story.p1_title": "家族經營",
        "story.p1_desc": "不是企業。是熱愛公路旅行的家族。",
        "story.p2_title": "手工改裝",
        "story.p2_desc": "我們自己設計和改裝了車輛。",
        "story.p3_title": "在地知識",
        "story.p3_desc": "我們住在這裡。我們知道隱藏的寶藏。",
        "story.quote": "「我們不是開了一家租車公司。我們造了自己想旅行的車——然後與你分享。」",
        "vehicles.probox_story": "我們的超人氣緊湊型探險車。低燃費、極致輕巧易於停車，提供5個座位與超大行李收納空間。情侶自駕的首選車款。",
        "vehicles.bongo_story": "我們的手工改裝巡航車。寬敞舒適，即使遇到陰雨天也能在車內悠閒度過。車幅窄好操控，雖然空間大但在日本狹窄路段也非常好駕駛。",
        "vehicles.daihatsu_badge": "🆕 全新登場 · 7月1日",
        "vehicles.daihatsu_name": "Daihatsu 輕型露營車",
        "vehicles.daihatsu_story": "超輕便ルーフテント露營車。可容納多達4人（車頂帳2名，車內2名），帳篷與車內相通可直接從內部上下，視野極佳。車身最為小巧，在狹窄的日本道路上行駛最為輕鬆省油。強烈推薦情侶夫妻體驗！",
        "vehicles.spec_rooftent_indoor": "車內直接直通車頂帳",
