        "home.hero.badge": "🇯🇵 福岡家庭經營露營車租賃",
        "home.hero.title": "用您的方式<br>探索九州",
        "home.hero.desc": "我們是一對在福岡經營手作露營車租賃的夫妻。在別府泡溫泉、驅車前往阿蘇火山口、在海景中醒來 — 全包式費用每日 22,000 日圓起。",
