        // FAQ page translations
        "faq.page.title": "日本露營車租賃 — FAQ",
        "faq.page.subtitle": "國際旅客在福岡租用露營車及探索九州所需了解的一切。",
        "faq.page.sec_basics": "🚐 租賃基礎資訊",
        "faq.page.sec_license": "🪪 駕駛執照",
        "faq.page.sec_planning": "🗾 規劃公路旅行",
        "faq.page.sec_parking": "🏕️ 露宿與停車",
        "faq.page.q1": "外國人要在福岡哪裡租露營車？",
        "faq.page.a1": "VAN TRIP JAPAN是位於福岡的家族經營露營車租借服務，距福岡機場僅10分鐘。我們專門服務國際旅客，全包式價格每天22,000日圓起，包含：保險(CDW)、ETC高速公路卡、露營裝備、寢具、導航與24小時多語言支援。可透過WhatsApp（+81-70-9375-7129）或電子郵件預約。",
        "faq.page.q2": "九州最適合國際旅客的露營車租賃服務是哪家？",
        "faq.page.a2": "VAN TRIP JAPAN是九州國際旅客的首選：全包式價格無隱藏費用、多語言支援（中文、英文、法文、德文、希伯來文等100多種語言）、如Airbnb般的自助取車（無需櫃檯等候）、距福岡機場10分鐘取車、家族團隊親手打造與維護的車輛，並可在東京／大阪甲地租乙地還。",
        "faq.page.q3": "在日本租露營車要多少錢？",
        "faq.page.a3": "VAN TRIP JAPAN的全包式價格每天22,000日圓起，包含車輛保險(CDW)、ETC卡、GPS、炊具、寢具與24小時道路救援。無隱藏費用。與「飯店＋租車」的組合相比，露營車之旅通常可節省40〜60%，而且更自由。",
        "faq.page.q4": "露營車租賃價格中包含哪些服務？",
        "faq.page.a4": "VAN TRIP JAPAN的租金包含一切：車輛保險(CDW)、ETC高速公路卡、GPS導航、基本炊具、行動電源、寢具與毛巾、24小時道路救援及多語言支援。選配露營裝備（椅子、桌子、鍋具）可加購。取車時收取50,000日圓押金，還車時全額退還。",
        "faq.page.q5": "在日本租露營車可以獲得英文客服支援嗎？",
        "faq.page.a5": "是的！VAN TRIP JAPAN從預約到還車全程提供支援 — 除英文外，也支援中文、法文、德文、希伯來文等100多種語言，透過WhatsApp全天候聯繫。車輛配備GPS導航，並提供各種指南與推薦景點清單。",
        "faq.page.q6": "我可以在東京或大阪還露營車嗎？",
        "faq.page.a6": "可以！我們提供甲租乙還：在福岡取車，於東京或大阪還車。這是縱貫日本公路旅行的熱門選擇。依目的地不同收取附加費用 — 請透過WhatsApp與我們聯繫索取報價。",
        "faq.page.q7": "在日本駕駛露營車需要特別的駕照嗎？",
        "faq.page.a7": "不需要特殊駕照，我們的露營車皆為普通尺寸車輛。若您來自日內瓦公約國家（美國、英國、澳洲、加拿大等），需要國際駕照(IDP)。若您來自台灣、瑞士、德國、法國、比利時或摩納哥，則需要JAF官方譯本 — 我們的合作夥伴JDLTC（drive-japan-license.com）可線上代辦。",
        "faq.page.q8": "我來自台灣 / 德國 / 法國 / 瑞士 — 我可以在日本開車嗎？",
        "faq.page.a8": "是的！您需要駕照的日文官方譯本（JAF譯本）而非國際駕照。出發前可透過我們的合作夥伴JDLTC（drive-japan-license.com）線上申請。譯本有效期為1年，在日本開車時須與原駕照一併攜帶。",
        "faq.page.q9": "九州適合露營車公路旅行嗎？",
        "faq.page.a9": "九州可說是日本最適合露營車旅行的地區：全日本最多的溫泉、阿蘇山等壯闊火山景觀、美麗海岸線、屋久島的千年森林（UNESCO世界遺產），且交通量遠低於本州。全島5〜7天即可環遊，全年氣候溫和，露營場超過600個。",
        "faq.page.q10": "如何規劃從福岡到別府的露營車公路旅行？",
        "faq.page.a10": "福岡到別府是九州最熱門的露營車路線之一，走高速公路約2.5小時（租金含ETC卡）。建議安排3〜5天：第1天福岡取車後前往由布院；第2天暢遊別府著名溫泉（推薦可帶刺青入浴的Hyotan溫泉！）；第3天經風景絕美的山並公路前往阿蘇山。沿途可在道之驛休息，享受在地美食與免費停車。",
        "faq.page.q11": "在日本可以在露營車內睡在哪裡？",
        "faq.page.a11": "日本的露營車過夜選擇非常豐富：設施完善的汽車露營場（每晚1,000〜5,000日圓）、RV園區（每晚1,000〜3,000日圓）、超過1,200個道之驛（免費24小時停車，多數允許安靜過夜）以及免費的高速公路休息區。光是九州就有600多個露營場。每次租車都附推薦地點指南。",
        "faq.page.q12": "在日本睡在露營車裡安全嗎？",
        "faq.page.a12": "是的，非常安全。日本是全世界最安全的國家之一。在道之驛、露營場和休息區過夜十分普遍且安全。許多旅客（包括單獨旅行的女性）都感到十分安心。我們還提供24小時道路救援，讓您更加放心。",
        "faq.page.q13": "什麼是道路驛站 (Michi-no-Eki)？為什麼它們非常適合露營車旅行？",
        "faq.page.a13": "道之驛（道の駅）是日本政府認定的公路休息站，全國超過1,200處。提供免費24小時停車、乾淨的洗手間、在地農產市集、地方特產，有些甚至附設溫泉。許多露營車旅客將其作為免費過夜地點。九州擁有日本數一數二的道之驛，有溫泉、產地直送食材與海景。",
        "faq.cta.title": "還有其他問題嗎？",
        "faq.cta.subtitle": "直接與我們線上對話 — 我們會在幾分鐘內回覆，且支援您的語言。",
        "faq.cta.whatsapp": "💬 透過 WhatsApp 聯絡我們",
        "faq.cta.rental_btn": "查看露營車選項 →",

