        "home.news.btn": "訂閱",
        "home.guides.tag": "推薦",
        "home.guides.title": "熱門旅遊指南",
        "home.guide1.title": "露營車 vs 飯店：真實成本比較",
        "home.guide1.desc": "租露營車真的比訂飯店加火車便宜嗎？我們以九州7天行程實際試算。",
        "home.guide2.title": "外國人可以在日本開車嗎?駕照與譯本規定",
        "home.guide2.desc": "國際駕照(IDP)、台灣駕照所需的日文譯本，以及日本交通規則完整解說。",
        "home.guides.read": "閱讀指南 →",
        "home.facts.title": "日本自駕與車泊：必知重點",
        "home.facts.rules": "<strong style=\"color: var(--color-accent, #d4a853);\">交通規則：</strong>日本靠左行駛。市區限速約30–40 km/h，國道50–60 km/h，高速公路80–120 km/h。全車乘客須繫安全帶，酒駕標準為0.0% — 日本對酒後駕駛採嚴格零容忍。",
        "home.facts.license": "<strong style=\"color: var(--color-accent, #d4a853);\">駕照規定：</strong>1949年日內瓦公約簽署國（美國、英國、澳洲等）的旅客可持國際駕照(IDP)駕駛。來自台灣、瑞士、德國、法國、比利時、摩納哥的旅客則需要駕照的日文譯本（<a href=\"https://drive-japan-license.com/\" target=\"_blank\" style=\"color: var(--color-accent, #d4a853); text-decoration: underline;\">可透過JDLTC取得</a>）。",
        "home.facts.camping": "<strong style=\"color: var(--color-accent, #d4a853);\">露營地：</strong>九州有超過200個露營場，包括免費的道之驛(michi-no-eki)與高級豪華露營設施。熱門目的地：阿蘇火山口、別府溫泉、國東半島、屋久島、霧島連山。",
        "home.facts.author": "<strong>撰寫者：</strong>VAN TRIP JAPAN創辦人Doko & Karen。定居福岡的夫妻團隊，曾開車走遍日本47個都道府縣。",
        "home.facts.updated": "<strong>最後更新：</strong><time datetime=\"2026-06-13\">2026年6月13日</time>｜<strong>參考資料：</strong><a href=\"https://www.npa.go.jp/english/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">日本警察廳</a>、<a href=\"https://www.jaf.or.jp/e/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">日本自動車聯盟(JAF)</a>",

