        "story.sec1_badge": "   הסיפור שלנו",
        "story.sec1_title": "שני אנשים, צי 100% יפני, תשוקה משותפת אחת",
        "story.sec1_subtitle": "אנחנו לא תאגיד השכרה ענק. אנחנו זוג נשוי שבוחר באהבה כל רכב ורכב.",
        "story.sec1_text1": "אצלנו אין מוקדי שירות טלפוניים, אין תסריטי שיחה של תאגידים ואין שירות מנוכר. כשאתם שוכרים אצלנו, אתם נתמכים ישירות על ידינו — ואנלייפרים (vanlifers) מנוסים שבילו שנים בדרכים. בחרנו כל אחד מהרכבים היפניים הבטוחים, האמינים והאיכותיים ביותר שלנו מתוך נקודת המבט המקצועית שלנו. כל ואן מציע חיסכון יוצא מן הכלל בדלק וקלות נהיגה קיצונית בכבישים הצרים והמפותלים של יפן.",
        "story.sec1_text2": "VAN TRIP JAPAN הוקמה ומנוהלת על ידי קארן, חובבת מושבעת ואמיתית של שטח ואאוטדור מזה שנים, יחד עם בעלה. הקמנו את החנות הקטנה הזו כי אנחנו מאמינים שטיול קמפרוואן ביפן צריך להרגיש בטוח, חם ואותנטי. אנחנו כאן כדי לתמוך בטיול שלכם עם ליווי אישי 24/7, מסלולים בהתאמה אישית והטיפים המקומיים הכי טובים שלא תמצאו בשום מדריך טיולים.",

        "story.label": "🏠 הסיפור שלנו",
        "story.caption": "👋 קארן ובעלה — המארחים שלכם",
        "story.title": "צוות של בעל ואישה — ואנלייפרים אמיתיים",
        "story.sub": "צי רכבים 100% יפני, שנבחר בקפידה תוך התמקדות בבטיחות מירבית וחיסכון מצוין בדלק.",
        "story.text": "אנחנו סוכנות קטנה להשכרת קמפרים בניהול זוגי בפוקואוקה. כוואנלייפרים מנוסים, אנו בוחרים כל רכב מתוך נקודת המבט המקצועית של מטייל בדרכים. הצי שלנו מורכב אך ורק מרכבים יפניים איכותיים ובטיחותיים ביותר (כמו ה-Hijet Truck, ה-Bongo וה-Probox האמינים במיוחד) — מה שמבטיח עמידה בתקני הבטיחות הגבוהים ביותר, נהיגה קלה במיוחד ברחובות צרים, וחיסכון מצוין בצריכת הדלק. הבעלים שלנו, קארן, היא חובבת שטח ואאוטדור מזה שנים. תכננו ובנינו את הוואנים האלה בעצמנו כדי להעניק לכם טיול בטוח, חם ואותנטי בין פניני החמד הנסתרות של יפן.",
        "story.p1_title": "בעל ואישה",
        "story.p1_desc": "צוות קטן, מסור ומלא תשוקה של מטיילים מנוסים.",
