        "vehicles.probox_story": "הגלאי הקומפקטי שלנו. חיסכון מצוין בדלק, קומפקטי במיוחד וקל לחניה, עם 5 מושבים ומקום עצום למזוודות וציוד. מושלם לזוגות.",
