        "planner.step1.opt3.desc": "חוקר קיושו הגדול. מכסה את כל האי כולל נגסאקי, קגושימה ועוד.",
        "planner.step2.q": "מה תרצו לחוות בטיול?",
        "planner.step2.opt1.title": "♨️ מעיינות חמים והרי געש",
        "planner.step2.opt1.desc": "הירגעו בכפרי אונסנים מסורתיים (באפו, קורוקאווה) וחקרו פסגות געשיות.",
        "planner.step2.opt2.title": "🌋 טבע והרפתקאות",
        "planner.step2.opt2.desc": "חתירה בסירה בקניון טקאצ'יהו, טרקים במסלולי קוג'ו ונסיעה במעברי הרים מרהיבים.",
        "planner.step2.opt3.title": "🌊 כבישי חוף וגלישה",
