        "home.banner.title": "הקרוואן שלכם מחכה",
        "home.banner.desc": "צ'ק-אין עצמאי, בלי ניירת ובלי דלפקים. אוספים את המפתחות מתיבת המפתחות ויוצאים לדרך — גם אם הטיסה נוחתת בחצות.",
