        "home.guides.title": "מדריכי טיולים פופולריים",
        "home.guide1.title": "קרוואן מול מלון: השוואת העלויות האמיתית",
        "home.guide1.desc": "האם השכרת קרוואן באמת זולה יותר ממלונות ורכבות? חישבנו את המספרים לטיול של 7 ימים בקיושו.",
        "home.guide2.title": "האם זרים יכולים לנהוג ביפן? רישיון ו-IDP",
        "home.guide2.desc": "כל מה שצריך לדעת על רישיון נהיגה בינלאומי (IDP), תרגום רישיון ליפנית וחוקי התנועה.",
        "home.guides.read": "לקריאת המדריך ←",
        "home.facts.title": "נהיגה וחיי ואן ביפן: עובדות חיוניות",
        "home.facts.rules": "<strong style=\"color: var(--color-accent, #d4a853);\">חוקי נהיגה:</strong> ביפן נוהגים בצד שמאל. מגבלות מהירות: כ-30–40 קמ\"ש בעיר, 50–60 קמ\"ש בכבישים ארציים ו-80–120 קמ\"ש בכבישים מהירים. חובת חגורה לכל הנוסעים, ורמת האלכוהול המותרת היא 0.0% — אפס סובלנות מוחלטת לשתייה ונהיגה.",
        "home.facts.license": "<strong style=\"color: var(--color-accent, #d4a853);\">דרישות רישיון:</strong> מבקרים ממדינות אמנת ז'נבה 1949 (כולל ישראל, ארה\"ב ובריטניה) יכולים לנהוג עם רישיון נהיגה בינלאומי (IDP). מבקרים משווייץ, גרמניה, צרפת, בלגיה, מונקו וטייוואן זקוקים לתרגום יפני רשמי של הרישיון (<a href=\"https://drive-japan-license.com/\" target=\"_blank\" style=\"color: var(--color-accent, #d4a853); text-decoration: underline;\">זמין דרך JDLTC</a>).",
        "home.facts.camping": "<strong style=\"color: var(--color-accent, #d4a853);\">קמפינג:</strong> בקיושו יותר מ-200 אתרי קמפינג, כולל אתרים עירוניים חינמיים (מיצ'י-נו-אקי) ואתרי גלמפינג יוקרתיים. יעדים מומלצים: קלדרת אסו, מעיינות בפו, חצי האי קוניסאקי, יאקושימה והרי קירישימה.",
        "home.facts.author": "<strong>נכתב על ידי:</strong> דוקו וקארן, מייסדי VAN TRIP JAPAN. זוג נשוי מפוקואוקה שטייל בוואן בכל 47 המחוזות של יפן.",
        "home.facts.updated": "<strong>עדכון אחרון:</strong> <time datetime=\"2026-06-13\">13 ביוני 2026</time> | <strong>מקורות:</strong> <a href=\"https://www.npa.go.jp/english/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">סוכנות המשטרה הלאומית של יפן</a>, <a href=\"https://www.jaf.or.jp/e/\" target=\"_blank\" rel=\"noopener\" style=\"color: var(--color-accent, #d4a853);\">התאחדות הרכב היפנית (JAF)</a>",

